  .dialog { position: relative; inset: auto; margin: 0; }
  .backdrop{position:fixed;inset:0;z-index:10000;display:grid;place-items:center;padding:clamp(.75rem,3vw,1.5rem);background:#000b}.dialog{width:min(100%,30rem);max-height:calc(100dvh - 1.5rem);overflow-y:auto;border:1px solid hsl(var(--border));border-radius:1rem;background:hsl(var(--card));color:hsl(var(--foreground));padding:clamp(1rem,4vw,1.5rem);box-shadow:0 1.5rem 4rem #0006}.kicker{margin:0 0 .4rem;color:hsl(var(--muted-foreground));font-size:.72rem;font-weight:700;letter-spacing:.08em}.dialog h2{margin:0;font-size:1.15rem}.copy{margin:.75rem 0 1rem;color:hsl(var(--muted-foreground));font-size:.9rem;line-height:1.6}.links{display:flex;flex-wrap:wrap;gap:.75rem 1.2rem;margin-bottom:1.1rem}.links a{color:hsl(var(--primary));font-size:.85rem;text-decoration:underline;text-underline-offset:3px}.check{display:flex;gap:.55rem;align-items:flex-start;font-size:.85rem;line-height:1.45;cursor:pointer}.check input{appearance:none;width:1.1rem;height:1.1rem;flex:0 0 1.1rem;margin:.15rem 0 0;border:2px solid hsl(var(--primary));border-radius:.25rem;background:hsl(var(--card));accent-color:hsl(var(--primary));display:grid;place-content:center}.check input::before{content:'✓';font-size:.8rem;font-weight:800;color:hsl(var(--primary-foreground));transform:scale(0);line-height:1}.check input:checked{background:hsl(var(--primary))}.check input:checked::before{transform:scale(1)}.dialog button{width:100%;margin-top:1.25rem;border:0;border-radius:.65rem;padding:.7rem 1rem;background:hsl(var(--primary));color:hsl(var(--primary-foreground));font-weight:700}.dialog button:disabled{cursor:not-allowed;opacity:.45}
